    protocol:{label:'Protocole complet · non exécuté',file:'docs/07-evaluation/protocole-utilisateur.md'},
    course3:{label:'Cours 3 · personas / tâches',detail:'Support local CM/Cours3.pdf : personas, scénarios et analyse des tâches.'},
